public class ImportNecessityCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("same package needs none", false,
                ImportNecessityChecker.needsImport("com.app", "com.app.Widget"));
        check("java.lang needs none", false,
                ImportNecessityChecker.needsImport("com.app", "java.lang.String"));
        check("subpackage of java.lang still needs one", true,
                ImportNecessityChecker.needsImport("com.app", "java.lang.reflect.Field"));
        check("reason same package", "SAME_PACKAGE",
                ImportNecessityChecker.reason("com.app", "com.app.Widget"));
        check("reason java lang", "JAVA_LANG",
                ImportNecessityChecker.reason("com.app", "java.lang.Integer"));
        check("reason default package", "DEFAULT_PACKAGE",
                ImportNecessityChecker.reason("com.app", "Helper"));
        check("same package wins for a file in java.lang", "SAME_PACKAGE",
                ImportNecessityChecker.reason("java.lang", "java.lang.String"));
        check("file in the default package", "NEEDED",
                ImportNecessityChecker.reason("", "java.util.Map"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

