public class ImportNecessityChecker {

    public static boolean needsImport(String currentPackage, String fullyQualifiedName) {
        return reason(currentPackage, fullyQualifiedName).equals("NEEDED");
    }

    public static String reason(String currentPackage, String fullyQualifiedName) {
        if (fullyQualifiedName == null) {
            return "DEFAULT_PACKAGE";
        }
        int lastDot = fullyQualifiedName.lastIndexOf('.');
        if (lastDot < 0) {
            return "DEFAULT_PACKAGE";
        }
        String owner = fullyQualifiedName.substring(0, lastDot);
        String here = currentPackage == null ? "" : currentPackage;
        if (owner.equals(here)) {
            return "SAME_PACKAGE";
        }
        if (owner.equals("java.lang")) {
            return "JAVA_LANG";
        }
        return "NEEDED";
    }
}
